import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"决策点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/decision-points.md","filePath":"guide/decision-points.md","lastUpdated":1792083553000}'),i={name:"guide/decision-points.md"};function o(l,t,s,h,n,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="决策点" tabindex="-1">决策点 <a class="header-anchor" href="#决策点" aria-label="Permalink to &quot;决策点&quot;">​</a></h1><p>决策点表示角色在回合内允许的<strong>操作数量</strong>。</p><blockquote><p>决策点由游戏平衡常数设置，与角色能力值无关。每个角色的决策点是独立的。</p></blockquote><h2 id="决策点配额" tabindex="-1">决策点配额 <a class="header-anchor" href="#决策点配额" aria-label="Permalink to &quot;决策点配额&quot;">​</a></h2><p>默认情况下，回合内各类行动各限一次，称为&quot;配额&quot;：</p><table tabindex="0"><thead><tr><th>行动</th><th>默认配额</th></tr></thead><tbody><tr><td>普通攻击</td><td>1</td></tr><tr><td>战技</td><td>1</td></tr><tr><td>爆发技</td><td>1</td></tr><tr><td>魔法</td><td>1</td></tr><tr><td>物品</td><td>1</td></tr><tr><td>协同确认</td><td>不限次数，仍受决策点预算限制</td></tr></tbody></table><p>被动技能和特效可以操作决策点及其配额，赋予动态策略性。</p><div class="info custom-block"><p class="custom-block-title">临时全能配额</p><p>临时全能配额叠加到普攻、战技、爆发技、物品与其他动作配额，魔法配额不接受临时全能加成。回合结束只清理回合角色本人的临时配额。</p></div><h2 id="初始化与补充" tabindex="-1">初始化与补充 <a class="header-anchor" href="#初始化与补充" aria-label="Permalink to &quot;初始化与补充&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>数值</th></tr></thead><tbody><tr><td>入队时初始决策点及上限</td><td>1</td></tr><tr><td>首次非吟唱回合的上限</td><td>2（回合入口提升 1）</td></tr><tr><td>回合开始时补充</td><td>上限的一半（向下取整，至少 1）</td></tr><tr><td>每次非吟唱回合开始</td><td>上限 +1（最多 7）</td></tr><tr><td>完全行动不能/行动受限</td><td>仅补充上限的 1/4（向下取整，至少 1）</td></tr></tbody></table><h2 id="使用消耗" tabindex="-1">使用消耗 <a class="header-anchor" href="#使用消耗" aria-label="Permalink to &quot;使用消耗&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行动</th><th>消耗</th></tr></thead><tbody><tr><td>普通攻击</td><td>1 决策点</td></tr><tr><td>战技 / 魔法</td><td>2 决策点</td></tr><tr><td>物品</td><td>1 决策点</td></tr><tr><td>回合内爆发技</td><td>2 决策点</td></tr><tr><td>回合外爆发技</td><td>3 决策点</td></tr><tr><td>协同确认</td><td>协调方 1 决策点；协作方另付自身动作成本</td></tr></tbody></table><h2 id="硬直时间-多次行动" tabindex="-1">硬直时间（多次行动） <a class="header-anchor" href="#硬直时间-多次行动" aria-label="Permalink to &quot;硬直时间（多次行动）&quot;">​</a></h2><p>当回合内行动次数 &gt; 1 时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回合结束时硬直时间 = 最长一次行动的硬直时间 + 本回合已使用的决策点数量</span></span></code></pre></div><p>没有多次计数行动时，按本回合动作硬直的最大值结算。</p><h2 id="特殊情况" tabindex="-1">特殊情况 <a class="header-anchor" href="#特殊情况" aria-label="Permalink to &quot;特殊情况&quot;">​</a></h2><ul><li>回合内吟唱魔法 → 直接结束回合</li><li>预释放爆发技的结算也沿用主循环；保留的计数达到多行动条件时仍使用正常聚合规则</li><li>先行动再吟唱 → 硬直时间累计到吟唱结算的回合</li></ul><p>普通魔法与预释放爆发技的结算回合不补点，保留发起回合的计数。协同魔法结算同样不补点，但会清空协作方上一正常回合已消费的计数，防止把旧动作重复加入本次结算。</p><p>协作动作只消耗 B 的当前 DP 和对应配额，不增加 B 上一正常回合的行动次数或已用 DP 统计。结算失败计默认 3 的失败尝试硬直，不额外扣 DP 或增加行动次数；可以在剩余预算与配额内重新决策。参见<a href="./chain-action.html">协同行动</a>和<a href="./skills-magic.html">魔法</a>。</p>',20)])])}const u=d(i,[["render",o]]);export{b as __pageData,u as default};
